components.css:
/* Baby blue glass: stable ink, translucent surfaces, one slow atmospheric motion. */
:root {
  --ink:#193b57; --muted:#3a536a; --paper:#f5faff; --ground:#d8eafa;
  --panel:#e5f2fd; --line:#b2ccdf; --strong-line:#6889a2;
  --accent:#a1cef1; --accent-ink:#154f79; --shell:#d4eafa;
  --focus:#246b9c; --error:#a5263d; --success:#21674e;
  --radius:10px; --mono:"SFMono-Regular",Consolas,"Liberation Mono",monospace;
  --sans:-apple-system,BlinkMacSystemFont,"Segoe UI","Helvetica Neue",Arial,"PingFang SC","Microsoft YaHei",sans-serif;
  font-family:var(--sans); color:var(--ink); background:var(--ground); font-size:15px;
  font-synthesis:none; color-scheme:light; scrollbar-color:#7198b7 var(--ground);
}
*{box-sizing:border-box}body{margin:0;min-height:100svh;isolation:isolate;background:linear-gradient(145deg,#edf7ff 0%,#c5e3fa 50%,#e7f2fc 100%)}
/* Diffuse cloud banks dissolve into a baby-blue sky; no hard cloud outlines. */
body::before,body::after{content:"";position:fixed;inset:-15%;z-index:-1;pointer-events:none;animation:blue-drift 48s ease-in-out infinite alternate}
body::before{background:linear-gradient(155deg,#a5cef1 0%,#c2e1f9 48%,#b4d8f5 100%)}
body::after{background:
radial-gradient(ellipse 25% 12% at 9% 23%,rgba(255,255,255,.9) 0%,rgba(246,252,255,.7) 36%,transparent 76%),
radial-gradient(ellipse 19% 17% at 24% 18%,rgba(251,254,255,.94) 0%,rgba(249,253,255,.61) 37%,transparent 74%),
radial-gradient(ellipse 28% 10% at 39% 27%,rgba(247,253,255,.82) 0%,rgba(244,251,255,.44) 39%,transparent 75%),
radial-gradient(ellipse 27% 11% at 96% 56%,rgba(255,255,255,.88) 0%,rgba(251,254,255,.57) 40%,transparent 75%),
radial-gradient(ellipse 19% 16% at 81% 51%,rgba(254,255,255,.94) 0%,rgba(249,253,255,.5) 42%,transparent 76%),
radial-gradient(ellipse 27% 10% at 66% 60%,rgba(247,252,255,.8) 0%,rgba(241,250,255,.43) 40%,transparent 76%),
radial-gradient(ellipse 37% 12% at 22% 91%,rgba(255,255,255,.75) 0%,rgba(245,252,255,.44) 40%,transparent 78%);
filter:blur(12px);animation-name:cloud-drift}
@keyframes cloud-drift{0%{transform:translate(-3%,1%) scale(1)}50%{transform:translate(2%,-1%) scale(1.035)}100%{transform:translate(5%,2%) scale(1.02)}}
@keyframes blue-drift{0%{transform:translate(-3%,-2%) scale(1)}50%{transform:translate(3%,2%) scale(1.06)}100%{transform:translate(-1%,5%) scale(1.02)}}
.motion-paused body::before,.motion-paused body::after,.page-hidden body::before,.page-hidden body::after{animation-play-state:paused}
@media(prefers-reduced-motion:reduce){body::before,body::after{animation:none}}button,input,select,textarea{font:inherit;color:inherit}
main{max-width:1184px;padding:0 40px 36px;margin:0 auto}
header{display:flex;justify-content:space-between;align-items:center;gap:24px;padding:38px 0 28px;border-bottom:1px solid rgba(75,122,159,.24)}
h1{font-size:30px;font-weight:700;letter-spacing:-.025em;line-height:1.35;margin:0 0 10px;text-wrap:balance}
h1::before{content:none}
h2{font-size:19px;font-weight:700;line-height:1.4;margin:0}
p{margin:8px 0;line-height:1.65;color:var(--muted)}header p{margin:0;font-size:14px}
a{color:var(--ink);text-underline-offset:4px;text-decoration-thickness:1px}
.header-actions{display:flex;align-items:center;gap:20px;flex-shrink:0;font-size:13px}
.header-actions a{white-space:nowrap}.header-actions .quiet{background:rgba(255,255,255,.58);border-color:var(--strong-line);color:var(--ink)}
button,.button{min-height:42px;padding:10px 14px;border:1px solid var(--strong-line);border-radius:var(--radius);background:var(--paper);cursor:pointer;font-size:13px;font-weight:600;transition:background-color 120ms ease-out}
button:disabled{color:var(--muted);background:var(--panel);cursor:wait}button:active,.button:active{background:#c2dff5}
input,textarea{caret-color:var(--accent-ink)}input,select,textarea,button,a,summary{-webkit-tap-highlight-color:transparent}
::selection{background:#b6dbf8;color:var(--ink)}::placeholder{color:#4f6a80;opacity:1}
:focus-visible{outline:3px solid var(--focus);outline-offset:2px;box-shadow:0 0 0 2px white}
.skip-link{position:fixed;top:8px;left:12px;transform:translateY(-180%);z-index:10;background:var(--paper);padding:12px;color:var(--ink)}.skip-link:focus{transform:translateY(0)}
.quiet{background:transparent;font-size:13px}.hint,.muted{font-size:12px;line-height:1.65;color:var(--muted)}
.exchange{display:flex;justify-content:space-between;align-items:center;gap:24px;padding:18px 0;margin-bottom:26px;border-bottom:1px solid var(--line)}
.exchange-control{display:flex;align-items:center;gap:10px;flex-shrink:0;font-size:13px;font-weight:600}
.exchange-control>span{font-family:var(--mono);font-size:12px}
.exchange input{width:108px;min-height:42px;padding:8px 10px;background:var(--paper);border:1px solid var(--strong-line);border-radius:var(--radius);font-family:var(--sans);font-variant-numeric:tabular-nums;font-size:16px}
.exchange .muted{font-size:11px;max-width:410px;line-height:1.75;text-align:right}
.layout{display:grid;grid-template-columns:minmax(0,1.13fr) minmax(0,1fr);gap:32px;align-items:start}
.panel{background:rgba(255,255,255,.56);padding:26px;border:1px solid rgba(255,255,255,.88);border-radius:16px;box-shadow:0 12px 38px rgba(38,91,132,.08);-webkit-backdrop-filter:blur(22px) saturate(125%);backdrop-filter:blur(22px) saturate(125%)}
.section-head{display:flex;align-items:center;justify-content:space-between;gap:12px}.tag{font-size:11px;line-height:1.4;border:1px solid #94b4ce;color:var(--muted);padding:4px 7px;white-space:nowrap}
.top-hint{padding-bottom:18px;margin:10px 0 22px;border-bottom:1px solid var(--line)}.top-hint strong{color:var(--ink);font-weight:600}
.field{display:block;margin-bottom:22px;font-size:14px;font-weight:600}.field .hint{font-weight:400}.field>.section-head{min-height:20px}
.input{display:flex;align-items:center;min-width:0;min-height:55px;border:1px solid var(--strong-line);border-radius:var(--radius);background:rgba(255,255,255,.72);margin-top:8px}
.input input{width:100%;min-width:0;padding:12px 13px;border:0;background:transparent;font:600 25px/1.2 var(--sans);font-variant-numeric:tabular-nums;box-shadow:none;outline:none}
.input:focus-within{outline:3px solid var(--focus);outline-offset:2px;border-color:var(--ink);box-shadow:0 0 0 2px white}
.unit{color:var(--muted);white-space:nowrap;font-size:12px;font-weight:400;padding:0 13px 0 4px}
.input select{border:0;border-left:1px solid var(--line);background:var(--panel);align-self:stretch;max-width:139px;padding:8px 10px;font-size:13px;font-weight:400;border-radius:0 var(--radius) var(--radius) 0;flex-shrink:0}
.input select:focus-visible{outline-offset:-3px;box-shadow:none}
.price-pair{display:grid;grid-template-columns:1fr 1fr;gap:12px}.price-pair input{padding-right:2px;font-size:22px}.price-pair .unit{font-size:11px;padding-right:10px}
#price-anchor{font-size:11px;font-weight:400}#tax-conversion,#cash-conversion{margin:-15px 0 23px;min-height:20px;font-family:var(--mono);font-size:11px}
.presets{display:flex;gap:8px;flex-wrap:wrap}.presets:not(:empty){margin:12px 0}
.preset{display:flex;max-width:100%;border:1px solid var(--strong-line);border-radius:var(--radius);overflow:hidden}
.preset button{border:0;min-height:38px;font-size:12px;padding:7px 10px;overflow-wrap:anywhere}
.preset .remove-preset{border-left:1px solid var(--line);color:var(--muted);flex-shrink:0}
.preset-tools{margin-top:10px}.preset-tools summary{font-size:12px;font-weight:400;width:fit-content;text-decoration:underline;text-underline-offset:3px}
.preset-save{display:flex;gap:8px;margin-top:10px}.preset-save input{flex:1;min-width:0;border:1px solid var(--strong-line);border-radius:var(--radius);padding:10px;font-size:13px;background:rgba(255,255,255,.72)}.preset-save button{flex-shrink:0}
#preset-status:empty{display:none}
.cash-section{border-top:1px solid var(--line);padding-top:22px}.cash-section h2{font-size:17px}
.segments{display:grid;grid-template-columns:1fr 1fr;border:0;padding:0;margin:14px 0 8px;gap:8px}
.segments label{position:relative;min-width:0;display:flex;align-items:center;gap:8px;border:1px solid var(--strong-line);padding:11px 9px;background:rgba(255,255,255,.72);font-size:12px;cursor:pointer;border-radius:var(--radius)}
.segments input{appearance:none;margin:0;width:16px;height:16px;flex:0 0 16px;border:1px solid var(--strong-line);border-radius:50%;background:rgba(255,255,255,.72);position:relative}
.segments input:checked::after{content:"";position:absolute;inset:3px;background:var(--ink);border-radius:50%}
.segments label:has(input:checked){background:#d7ecfc;border-color:var(--accent-ink)}.segments input:focus-visible{box-shadow:0 0 0 2px white}
#basis-hint{min-height:20px;margin-bottom:17px}.cash-section .field{margin-bottom:22px}
summary{cursor:pointer;line-height:1.6;padding:4px 0}summary span{font-weight:400;color:var(--muted);font-size:12px;margin-left:8px}
.flight-details{border-top:1px solid var(--line);padding-top:14px;margin-top:18px}.flight-details>summary{font-size:14px;font-weight:600}
.trip-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:18px 0}.trip-grid label{font-size:12px;min-width:0}
.trip-grid input,.trip-grid select,.trip-grid textarea{display:block;width:100%;min-width:0;max-width:100%;padding:10px;margin-top:7px;border:1px solid var(--strong-line);background:rgba(255,255,255,.72);min-height:44px;border-radius:var(--radius);font-size:14px}
.trip-grid .wide{grid-column:1/-1}.trip-grid textarea{min-height:84px;resize:vertical}
.button{display:inline-block;text-decoration:none;color:var(--ink);background:var(--accent);border-color:var(--accent);font-size:14px;padding:12px 16px}
.results{min-width:0;scroll-margin-top:20px}
.result-main{background:linear-gradient(135deg,rgba(255,255,255,.69),rgba(222,240,255,.58));border:1px solid rgba(255,255,255,.88);border-bottom:0;border-radius:16px 16px 0 0;padding:0 25px 23px;-webkit-backdrop-filter:blur(22px) saturate(125%);backdrop-filter:blur(22px) saturate(125%)}
.result-main>.section-head{margin:0;padding:23px 0 0;color:var(--ink)}
.result-main h2{font-size:16px;font-weight:600}.result-main .section-head>span{font-size:11px;color:var(--muted);background:rgba(255,255,255,.6);padding:5px 9px;border-radius:20px}
.readout{display:flex;justify-content:space-between;gap:16px;align-items:center;margin:20px 0 6px}
.multiplier{display:flex;align-items:baseline;gap:8px;min-width:0}.multiplier>span:first-child{font-family:var(--sans);font-variant-numeric:tabular-nums;font-size:76px;font-weight:700;letter-spacing:-.035em;line-height:1.12;overflow-wrap:anywhere;min-width:0}
.times{font-size:15px;font-weight:500}.ratio-definition{border-left:1px solid var(--line);padding-left:15px;font-size:11px;color:var(--muted);line-height:1.7;flex-shrink:0}
.result-main p{font-size:12px;color:var(--accent-ink);min-height:20px;margin:12px 0 22px;line-height:1.6}
.result-rule{border-top:1px solid var(--strong-line)}
.money-row{display:flex;justify-content:space-between;align-items:baseline;gap:18px;padding:15px 0;border-bottom:1px solid var(--line)}
.money-row>span{font-size:13px;flex-shrink:0}.money-row>div{text-align:right;min-width:0;font-family:var(--sans);font-variant-numeric:tabular-nums;overflow-wrap:anywhere}
.money-row strong{font-size:24px;font-weight:600;display:block;letter-spacing:-.025em}.money-row small{font-size:11px;line-height:1.5;color:var(--muted);display:block;margin-top:5px}
.savings{border-bottom:0;padding-bottom:11px}.savings strong{color:var(--accent-ink)}
.save-rate{display:flex;align-items:center;justify-content:space-between;font-size:13px;gap:16px}.save-rate strong{font:600 18px var(--sans);color:var(--accent-ink)}
.result-main.loss .savings strong,.result-main.loss .save-rate strong{color:var(--error)}
.metrics{display:grid;grid-template-columns:1fr 1fr;border:1px solid rgba(255,255,255,.88);border-top:1px solid var(--line);background:rgba(255,255,255,.65);border-radius:0 0 16px 16px;box-shadow:0 14px 32px rgba(38,91,132,.07);-webkit-backdrop-filter:blur(22px);backdrop-filter:blur(22px)}
.metrics>div{padding:18px 20px;min-width:0}.metrics>div+div{border-left:1px solid var(--line)}
.metrics span,.metrics small{display:block;font-size:11px;color:var(--muted)}.metrics strong{font:600 27px var(--sans);display:block;margin:8px 0 7px;overflow-wrap:anywhere;letter-spacing:-.02em}
.breakdown{margin-top:25px;padding:0 2px}.breakdown h2{font-size:14px;margin-bottom:13px}
.break-row{display:flex;justify-content:space-between;gap:18px;padding:10px 0;border-top:1px solid var(--line);font-size:12px}
.break-row>span:last-child{font-family:var(--mono);text-align:right;white-space:pre-line;font-size:11px;line-height:1.75}
.bar{display:flex;gap:2px;height:8px;margin:12px 0;background:#d1e5f5}.bar span:first-child{background:#447faa}.bar span:last-child{background:var(--accent)}
#break-note{font:11px/1.7 var(--mono);margin-top:9px}.error{color:var(--error)}#edge-note:empty{display:none}
.formulas{border-top:1px solid var(--strong-line);margin-top:20px;padding-top:13px;font-size:12px;scroll-margin-top:24px}.formulas summary{font-weight:600}.formulas ul{line-height:1.9;padding-left:18px;color:var(--muted)}
footer{border-top:1px solid var(--strong-line);margin-top:30px;padding-top:19px;display:flex;justify-content:space-between;flex-wrap:wrap;gap:13px;font-size:11px;color:var(--muted);line-height:1.7}
.text-button{min-height:24px;border:0;background:transparent;font-size:12px;font-weight:400;padding:0;text-decoration:underline;text-underline-offset:4px}.footer-note{flex-basis:100%;font-size:11px}
.mobile-result{display:none}[hidden]{display:none!important}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
@media(hover:hover) and (pointer:fine){button:hover{background:#d7eafa}.header-actions .quiet:hover{background:#d1e8fa}.button:hover{background:#badffc}.segments label:hover{background:#e0effb}a:hover{text-decoration-thickness:2px}}
