@media(max-width:800px){header{flex-direction:column;gap:18px;padding-top:28px}.header-actions{max-width:none;justify-content:flex-start;gap:22px}.exchange{align-items:flex-start;flex-direction:column;gap:10px}.exchange .muted{text-align:left;max-width:none}.layout{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:20px}.panel{padding:18px}.price-pair{grid-template-columns:1fr}.price-pair input{font-size:24px}.segments{grid-template-columns:1fr}.readout{flex-wrap:wrap;gap:8px}.ratio-definition{border:0;padding:0;line-height:1.5}.ratio-definition br{display:none}.metrics>div{padding:15px 12px}.metrics strong{font-size:22px}.money-row{gap:10px}.money-row>span{font-size:12px}.money-row strong{font-size:19px}}
