/* Narrow price controls keep their complete readout; units sit beneath the number. */
@media(max-width:640px){
  .price-pair .input{display:grid;grid-template-columns:minmax(0,1fr);padding-bottom:9px;gap:1px}
  .price-pair .input input{padding:11px 10px 2px;font-size:22px;width:100%}
  .price-pair .unit{padding:0 10px;font-size:11px;line-height:1.4}
}

/* Opaque fallback keeps the same palette on browsers without glass support. */
@supports not ((backdrop-filter:blur(1px)) or (-webkit-backdrop-filter:blur(1px))){.panel,.result-main,.metrics{background:#edf6fd}.mobile-result{background:#edf6fd}}
@media(prefers-reduced-transparency:reduce){.panel,.result-main,.metrics,.mobile-result{background:#edf6fd;-webkit-backdrop-filter:none;backdrop-filter:none}}

/* Flighty-inspired hierarchy: native type, compact secondary data, clear selection. */
header{border-bottom:0;padding-bottom:24px}h1{font-size:32px;letter-spacing:-.035em}
.header-actions{gap:8px}.header-actions>a{padding:10px 11px;border-radius:var(--radius);text-decoration:none;min-height:42px;display:flex;align-items:center}
.header-actions .quiet{background:rgba(255,255,255,.7);border-color:rgba(255,255,255,.9)}
.exchange{padding:14px 18px;border:1px solid rgba(255,255,255,.75);border-radius:16px;background:rgba(255,255,255,.32);-webkit-backdrop-filter:blur(18px);backdrop-filter:blur(18px);margin-bottom:24px}
.exchange input{background:rgba(255,255,255,.8)}
.tag{border:0;border-radius:20px;background:#d7eafa;color:var(--accent-ink);padding:5px 9px}
.segments{padding:4px;gap:4px;background:rgba(143,183,216,.2);border-radius:12px}
.segments label{justify-content:center;border:1px solid transparent;background:transparent;border-radius:9px;padding:10px 6px;min-height:44px;line-height:1.5}
.segments label:has(input:checked){background:rgba(255,255,255,.92);border-color:rgba(255,255,255,.95);color:var(--accent-ink);box-shadow:0 2px 6px rgba(44,83,114,.12);font-weight:600}
.segments input{position:absolute;opacity:0;width:1px;height:1px;pointer-events:none}
.segments label:has(input:focus-visible){outline:3px solid var(--focus);outline-offset:2px}
.metrics strong,.save-rate strong{font-variant-numeric:tabular-nums}
.metrics small,.money-row small{font-size:12px}.money-row small{font-weight:400}
.bar{border-radius:6px;overflow:hidden}.bar span{border-radius:6px}
@media(hover:hover) and (pointer:fine){.header-actions>a:hover{background:rgba(255,255,255,.55)}.segments label:hover{background:rgba(255,255,255,.45)}}
@media(max-width:1020px){h1{font-size:28px}.exchange{gap:14px}}
@media(max-width:800px){.exchange{padding:14px 16px}.header-actions{gap:6px}}
@media(max-width:640px){h1{font-size:24px}.header-actions{gap:4px}.header-actions>a{padding:9px 10px}.exchange{padding:14px 12px}.exchange-control{gap:6px}.exchange input{width:86px}.exchange button{padding:10px 8px}.mobile-result{left:10px;right:10px;bottom:10px;border:1px solid rgba(255,255,255,.95);border-radius:16px;padding:15px 14px max(15px,env(safe-area-inset-bottom))}.mobile-result span{font-family:var(--sans);font-variant-numeric:tabular-nums}.metrics strong{font-size:27px}.money-row strong{font-size:24px}}
@media(max-width:360px){h1{font-size:21px}.exchange input{width:80px}.exchange-control{gap:5px}.exchange button{min-height:38px}.mobile-result{left:8px;right:8px;padding-left:12px;padding-right:12px}}

/* Optional airfare search stays within the existing glass form. */
.fare-actions{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0 8px}
.fare-actions button{min-height:44px}
.fare-option{padding:18px 0;border-top:1px solid var(--line);font-size:14px}
.fare-option>strong{font-size:17px;font-variant-numeric:tabular-nums}
.fare-itinerary{white-space:pre-line;overflow-wrap:anywhere;font-size:12px;line-height:1.8}
.fare-confirm{display:flex;align-items:flex-start;gap:9px;font-size:12px;line-height:1.65;margin:12px 0}
.fare-confirm input{margin-top:4px;flex:0 0 17px;width:17px;height:17px;accent-color:var(--accent-ink)}
#fare-results a,.manual-search{font-size:12px;line-height:1.7}
#fare-results:not(:empty){margin-bottom:20px}
#cash-source{margin-top:-10px;margin-bottom:20px;overflow-wrap:anywhere}
